  def update_pos(pos)
    @file_mutex.synchronize {
      @file.pos = @seek
      @file.write "%016x" % pos
    }
    @pos = pos
  end

  def read_inode
    @inode
  end

  def read_pos
    @pos
  end
end

class MemoryPositionEntry
  def initialize
    @pos = 0

